import { cacheLife, cacheTag } from 'next/cache'

import { getPosts } from '@/lib/api'

async function getPostsCached() {
  'use cache'
  cacheTag('posts')
  cacheLife('hours')

  return getPosts()
}

export default async function Home() {
  const posts = await getPostsCached()

  return (
    <main>
      <h1>Blog Posts</h1>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>By {post.author}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}

